import { PageHeaderModule } from 'src/app/view/components/app/page-header/page-header.module';
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { HelpfulLinkRoutingModule } from './helpful-link-routing.module';
import { HelpfulLinkComponent } from './helpful-link.component';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { IonicModule } from '@ionic/angular';
import { AccountInterceptor } from 'src/app/core/utility/account.interceptor';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { LoadingModule } from '../../../../components/common/loading/loading.module';

import { FooterModule } from '../../../../components/app/footer/footer.module';


@NgModule({
  declarations: [HelpfulLinkComponent],
  imports: [
    PageHeaderModule,
    CommonModule,
    HelpfulLinkRoutingModule,
    IonicModule,
    HttpClientModule,
    FormsModule,
    ReactiveFormsModule,
    LoadingModule,
    
    FooterModule
  ],
  providers: [
    SliderService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ]
})
export class HelpfulLinkModule { }
