import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { IHelpfulLinkModel, HelpfulLinkModel } from '../../../../../data/model/site/SliderModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';

@Component({
  selector: 'app-helpful-link',
  templateUrl: './helpful-link.component.html',
  styleUrls: ['./helpful-link.component.scss']
})
export class HelpfulLinkComponent implements OnInit {

  addForm: FormGroup;
  updateForm: FormGroup;
  links: IHelpfulLinkModel[];
  segmentSelected = 'Update';

  constructor(
    private sliderService: SliderService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.addForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      url: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]]
    });

    this.updateForm = this.fb.group({
      id: ['', [Validators.required, Validators.min(1)]],
      name: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      url: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]]
    });
  }

  ionViewWillEnter() {

    this.onGetData();
  }

  onGetData() {

    SharedIonic.loading(this.loadingController);

    this.sliderService.GetAllHelpfulLink().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.links = res.data;
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onSelect(index: number | string): void {

    this.updateForm.setValue({
      id: this.links[+index].id,
      name: this.links[+index].name,
      url: this.links[+index].url
    });
  }

  onUpdate() {

    if (this.updateForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.sliderService.AddOrUpdateHelpfulLink(
        new HelpfulLinkModel(
          this.updateForm.value.id,
          this.updateForm.value.name,
          this.updateForm.value.url
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {

            this.updateForm.setValue({
              id: '',
              name: '',
              url: ''
            });
            this.onGetData();
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.sliderService.AddOrUpdateHelpfulLink(
        new HelpfulLinkModel(
          0,
          this.addForm.value.name,
          this.addForm.value.url
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {

            this.addForm.setValue({
              name: '',
              url: ''
            });
            this.onGetData();
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAdd();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm(id: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemove(+id);
          }
        }
      ]
    });

    await alert.present();
  }

  onRemove(id: number) {

    SharedIonic.loading(this.loadingController);

    this.sliderService.RemoveHelpfulLink(id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.updateForm.setValue({
            id: '',
            name: '',
            url: ''
          });
          this.onGetData();
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

}
