import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { HelpfulLinkComponent } from './helpful-link.component';

const routes: Routes = [{ path: '', component: HelpfulLinkComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HelpfulLinkRoutingModule { }
